import { useState } from "react";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { ScanText } from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { AIScanReceiptData } from "@/features/transaction/transationType";
import { toast } from "sonner";
import { useProgressLoader } from "@/hooks/use-progress-loader";
import { useAiScanReceiptMutation } from "@/features/transaction/transactionAPI";

interface ReceiptScannerProps {
  loadingChange: boolean;
  onScanComplete: (data: AIScanReceiptData) => void;
  onLoadingChange: (isLoading: boolean) => void;
}

const ReceiptScanner = ({
  loadingChange,
  onScanComplete,
  onLoadingChange,
}: ReceiptScannerProps) => {
  const [receipt, setReceipt] = useState<string | null>(null);

  const {
    progress,
    startProgress,
    updateProgress,
    doneProgress,
    resetProgress,
  } = useProgressLoader({ initialProgress: 10, completionDelay: 500 });

  const [aiScanReceipt] = useAiScanReceiptMutation();

  const handleReceiptUpload = async (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = event.target.files?.[0];
    if (!file) {
      toast.error("Please select a file");
      return;
    }
    if (!file.type.startsWith("image/")) {
      toast.error("Please upload an image file");
      return;
    }
    const formData = new FormData();
    formData.append("receipt", file);

    startProgress(10);
    onLoadingChange(true);
    // Simulate file upload and processing
    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target?.result as string;
      setReceipt(result);

      // Simulate scanning progress
      // Start progress
      let currentProgress = 10;
      const interval = setInterval(() => {
        const increment = currentProgress < 90 ? 10 : 1;
        currentProgress = Math.min(currentProgress + increment, 90);
        updateProgress(currentProgress);
      }, 250);

      aiScanReceipt(formData)
        .unwrap()
        .then((res) => {
          updateProgress(100);
          onScanComplete(res.data);
          toast.success("Receipt scanned successfully");
        })
        .catch((error) => {
          toast.error(error.data?.message || "Failed to scan receipt");
        })
        .finally(() => {
          clearInterval(interval);
          doneProgress();
          resetProgress();
          setReceipt(null);
          onLoadingChange(false);
        });
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-3">
      <Label className="text-sm font-medium">AI Scan Receipt</Label>
      <div className="flex items-start gap-3 border-b pb-4">
        {/* Receipt Preview */}
        <div
          className={`h-12 w-12 rounded-md border bg-cover bg-center ${
            !receipt ? "bg-muted" : ""
          }`}
          style={receipt ? { backgroundImage: `url(${receipt})` } : {}}
        >
          {!receipt && (
            <div className="flex h-full items-center justify-center text-muted-foreground">
              <ScanText color="currentColor" className="h-5 w-5 !stroke-1.5" />
            </div>
          )}
        </div>

        {/* Upload Input or Progress */}
        <div className="flex-1">
          {!loadingChange ? (
            <>
              <Input
                type="file"
                accept="image/*"
                onChange={handleReceiptUpload}
                className="max-w-[250px] px-1 h-9 cursor-pointer text-sm file:mr-2 
            file:rounded file:border-0 file:bg-primary file:px-3 file:py-px
             file:text-sm file:font-medium file:text-white 
             hover:file:bg-primary/90"
                disabled={loadingChange}
              />
              <p className="mt-2 text-[11px] px-2 text-muted-foreground">
                JPG, PNG up to 5MB
              </p>
            </>
          ) : (
            <div className="space-y-2 pt-3">
              <Progress value={progress} className="h-2 w-[250px]" />
              <p className="text-xs text-muted-foreground">
                Scanning receipt... {progress}%
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ReceiptScanner;

name: Issue Severity Labeler

on:
  issues:
    types: [opened, edited, reopened]

permissions:
  issues: write

jobs:
  apply-severity-label:
    runs-on: ubuntu-latest
    steps:
      - name: Map severity to labels
        uses: actions/github-script@v7
        with:
          script: |
            const issue = context.payload.issue;
            const body = issue.body || '';

            const severityLabels = [
              { name: 'priority:s1', color: 'b60205', description: 'Critical priority' },
              { name: 'priority:s2', color: 'd93f0b', description: 'High priority' },
              { name: 'priority:s3', color: 'fbca04', description: 'Medium priority' },
              { name: 'priority:s4', color: '0e8a16', description: 'Low priority' }
            ];

            for (const label of severityLabels) {
              try {
                await github.rest.issues.getLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: label.name
                });
              } catch (error) {
                if (error.status === 404) {
                  await github.rest.issues.createLabel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    ...label
                  });
                } else {
                  throw error;
                }
              }
            }

            let target = null;
            if (/S1 - Critical/i.test(body)) target = 'priority:s1';
            if (/S2 - High/i.test(body)) target = 'priority:s2';
            if (/S3 - Medium/i.test(body)) target = 'priority:s3';
            if (/S4 - Low/i.test(body)) target = 'priority:s4';

            const existing = issue.labels.map((l) => typeof l === 'string' ? l : l.name);
            const toRemove = existing.filter((name) => /^priority:s[1-4]$/i.test(name));

            for (const name of toRemove) {
              if (name !== target) {
                try {
                  await github.rest.issues.removeLabel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    issue_number: issue.number,
                    name
                  });
                } catch (error) {
                  if (error.status !== 404) throw error;
                }
              }
            }

            if (target && !existing.includes(target)) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue.number,
                labels: [target]
              });
            }

name: PR Auto Labeler

on:
  pull_request_target:
    types: [opened, synchronize, reopened, ready_for_review]

permissions:
  contents: read
  pull-requests: write

jobs:
  label:
    name: Apply path labels
    runs-on: ubuntu-latest
    steps:
      - name: Ensure labels exist
        uses: actions/github-script@v7
        with:
          script: |
            const labels = [
              { name: 'frontend', color: '1d76db', description: 'Changes frontend source code' },
              { name: 'ci/cd', color: '5319e7', description: 'Changes CI/CD workflows and automation' },
              { name: 'docs', color: '0e8a16', description: 'Documentation-only changes' },
              { name: 'dependencies', color: 'fbca04', description: 'Dependency updates' },
              { name: 'config', color: '0052cc', description: 'Configuration and environment changes' }
            ];

            for (const label of labels) {
              try {
                await github.rest.issues.getLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  name: label.name
                });
              } catch (error) {
                if (error.status === 404) {
                  await github.rest.issues.createLabel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    ...label
                  });
                } else {
                  throw error;
                }
              }
            }

      - name: Label pull request
        uses: actions/labeler@v6
        with:
          repo-token: ${{ secrets.GITHUB_TOKEN }}

import { parseAsBoolean, parseAsString, useQueryState } from "nuqs";

const useEditTransactionDrawer = () => {
  const [open, setOpen] = useQueryState(
    "edit",
    parseAsBoolean.withDefault(false)
  );
  const [transactionId, setTransactionId] = useQueryState(
    "transactionId",
    parseAsString.withDefault("")
  );
  const onOpenDrawer = (transactionId: string) => {
    setTransactionId(transactionId);
    setOpen(true);
  };

  const onCloseDrawer = () => {
    setTransactionId("");
    setOpen(false);
  };

  return {
    open,
    transactionId,
    onOpenDrawer,
    onCloseDrawer,
  };
};

export default useEditTransactionDrawer;

import { parseAsBoolean, parseAsStringEnum, useQueryState } from "nuqs";

type TransactionMode = "voice" | "scan" | "manual";

const useAddTransactionDrawer = () => {
  const [open, setOpen] = useQueryState(
    "addTransaction",
    parseAsBoolean.withDefault(false)
  );
  const [mode, setMode] = useQueryState(
    "addMode",
    parseAsStringEnum<TransactionMode>(["voice", "scan", "manual"]).withDefault("voice")
  );

  const onOpenDrawer = (initialMode: TransactionMode = "voice") => {
    setMode(initialMode);
    setOpen(true);
  };

  const onCloseDrawer = () => {
    setOpen(false);
    setMode("voice");
  };

  return { open, mode, setMode, onOpenDrawer, onCloseDrawer };
};

export default useAddTransactionDrawer;

