import { useEffect } from "react";
import { useAppDispatch, useTypedSelector } from "@/app/hook";
import { logout, updateCredentials } from "@/features/auth/authSlice";
import { useRefreshMutation } from "@/features/auth/authAPI";

const useAuthExpiration = () => {
  const { accessToken, expiresAt, refreshToken: storedRefreshToken } = useTypedSelector((state) => state.auth);
  const dispatch = useAppDispatch();
  const [refreshToken] = useRefreshMutation();

  useEffect(() => {
    const handleLogout = () => {

      dispatch(logout());
    };

    const handleTokenRefresh = async () => {
      try {

        if (!storedRefreshToken) {
          throw new Error("No refresh token stored");
        }

        const { accessToken, expiresAt, refreshToken: newRefreshToken } = await refreshToken({
          refreshToken: storedRefreshToken
        }).unwrap();
        dispatch(updateCredentials({ accessToken, expiresAt, refreshToken: newRefreshToken || storedRefreshToken }));


      } catch (error) {
        console.error("Token refresh failed, logging out...", error);
        handleLogout();
      }
    };

    if (accessToken && expiresAt) {
      const currentTime = Date.now();
      const timeUntilExpiration = expiresAt - currentTime;

      // Refresh slightly BEFORE it expires
      const bufferTime = 60 * 1000;

      if (timeUntilExpiration <= bufferTime) {
        // Token is already expired or very close to expiring
        handleTokenRefresh();
      } else {
        // Set a timeout to REFRESH the token right before it expires
        const timer = setTimeout(handleTokenRefresh, timeUntilExpiration - bufferTime);
        // Cleanup the timer on component unmount or token change
        return () => clearTimeout(timer);
      }
    }
  }, [accessToken, dispatch, expiresAt, refreshToken, storedRefreshToken]);
};

export default useAuthExpiration;

import {
  _TRANSACTION_FREQUENCY,
  _TransactionType,
  PAYMENT_METHODS_ENUM,
} from "@/constant";

type RecurringIntervalType =
  (typeof _TRANSACTION_FREQUENCY)[keyof typeof _TRANSACTION_FREQUENCY];
type PaymentMethodType =
  (typeof PAYMENT_METHODS_ENUM)[keyof typeof PAYMENT_METHODS_ENUM];

export interface CreateTransactionBody {
  title: string;
  type: _TransactionType;
  amount: number;
  description: string;
  category: string;
  date: string;
  isRecurring: boolean;
  recurringInterval?: RecurringIntervalType | null;
  paymentMethod: string;
  currency?: string;
}

export interface GetAllTransactionParams {
  keyword?: string;
  type?: _TransactionType;
  recurringStatus?: "RECURRING" | "NON_RECURRING";
  startDate?: string;
  endDate?: string;
  pageNumber?: number;
  pageSize?: number;
}

export interface TransactionType {
  _id: string;
  userId: string;
  title: string;
  type: _TransactionType;
  recurringStatus?: "RECURRING" | "NON_RECURRING";
  amount: number;
  originalAmount?: number | null;
  originalCurrency?: string | null;
  baseCurrencyAtTime?: string | null;
  exchangeRate?: number | null;
  rateSource?: "live" | "cached" | null;
  description: string;
  category: string;
  date: string;
  isRecurring: boolean;
  recurringInterval: RecurringIntervalType | null;
  nextRecurringDate: string | null;
  lastProcessed: string | null;
  status: string;
  paymentMethod: string;
  createdAt: string;
  updatedAt: string;
  id?: string;
}

export interface GetAllTransactionResponse {
  message: string;
  transactions: TransactionType[];
  pagination: {
    pageSize: number;
    pageNumber: number;
    totalCount: number;
    totalPages: number;
    skip: number;
  };
}

export interface AIScanReceiptData {
  title: string;
  amount: number;
  date: string;
  description: string;
  category: string;
  paymentMethod: string;
  type: "INCOME" | "EXPENSE";
  currency?: string;
  receiptUrl?: string;
  voiceUrl?: string;
  transcription?: string;
  confidence?: number;
  error?: string;
}

export interface AIScanReceiptResponse {
  success: boolean;
  message: string;
  data: AIScanReceiptData;
}

export interface GetSingleTransactionResponse {
  message: string;
  transaction: TransactionType;
}

export interface UpdateTransactionPayload {
  id: string;
  transaction: CreateTransactionBody;
}

export interface BulkTransactionType {
  title: string;
  type: _TransactionType;
  amount: number;
  category: string;
  description: string;
  date: string;
  paymentMethod: PaymentMethodType;
  isRecurring: boolean;
}

export interface BulkImportTransactionPayload {
  transactions: BulkTransactionType[];
}


